def execute(principal, tool, action, resource_id, arguments, approval):
    decision = policy.authorize_tool(principal, tool, action, resource_id, arguments, approval_id=approval)
    if not decision.allowed:
        return decision, None
    handler = handlers.get((tool, action))
    if handler is None:
        return ToolDecision(False, 'NO_TRUSTED_HANDLER_REGISTERED'), None
    return decision, handler(dict(arguments))
